LEVELS = {'approved_indication':'Regulatory indication','established_indication':'Established clinical use','randomized_phase2':'Randomized phase 2','early_clinical':'Exploratory human clinical','human_association':'Human association','mechanistic_human':'Mechanistic human study','hypothesis':'Unverified hypothesis'}

class ClaimCheck(BaseModel):
    query:str=Field(min_length=3,max_length=400)
    area:Literal['All','Oncology','Cardiometabolic','Microbiome']='All'

def graph_payload(area='All'):
    chosen=[r for r in CLAIMS if area=='All' or r['area']==area]
    ns={}; edges=[]
    def node(kind,label):
        key=kind+':'+label
        ns[key]={'id':key,'kind':kind,'label':label}
        return key
    for claim in chosen:
        c=node('Claim',claim['title'])
        for kind,field,rel in [('Disease','disease','indication'),('Intervention','intervention','intervention'),('Mechanism','mechanism','mechanistic assertion'),('Biomarker','biomarker','investigational biomarker')]:
            v=node(kind,claim[field]);edges.append({'from':c,'to':v,'relation':rel,'claim_id':claim['id']})
        for sid in claim['sources']:
            s=node('Source',sid);edges.append({'from':c,'to':s,'relation':'cites','claim_id':claim['id']})
    return {'claims':chosen,'sources':{sid:SOURCES[sid] for c in chosen for sid in c['sources']},'nodes':list(ns.values()),'edges':edges,'disclaimer':'Curated human-readable relationships; edges do not prove causality, efficacy, safety, or freedom to operate.'}

def assess(query,area='All'):
    words=set(re.findall(r'[a-z0-9]+',query.lower()))-{'the','and','for','with','from','that','this','into','have','could','would','what','does','therapy','bacterial','treatment','disease','clinical','are','was','our','its','can','how'}
    matches=[]
    for c in CLAIMS:
        if area!='All' and c['area']!=area:continue
        corpus=' '.join(str(c[k]) for k in ['title','disease','intervention','mechanism','biomarker','area']).lower()
        hit=sorted(w for w in words if len(w)>2 and w in corpus)
        if hit:matches.append({'claim':c,'matching_terms':hit,'match_count':len(hit)})
    matches.sort(key=lambda x:(-x['match_count'],x['claim']['id']))
    selected=matches[:8]
    flags=[]
    if not selected:flags.append('No curated claim matched. Do not infer an absence of scientific evidence; expand source retrieval.')
    if any(x['claim']['grade']=='hypothesis' for x in selected):flags.append('Hypothesis records have no attached verifying primary source in this release.')
    if any(x['claim']['grade'] in ('human_association','mechanistic_human') for x in selected):flags.append('Associational or mechanistic research cannot establish effectiveness of a bacteria-based therapeutic.')
    if any(x['claim']['grade'] in ('approved_indication','established_indication') for x in selected):flags.append('Any approved/established indication is disease- and product-specific; no cross-indication inference.')
    if any('patent' in w or 'fto' in w for w in words):flags.append('Patent search and freedom-to-operate are NOT performed by this graph; legal claim and jurisdiction review required.')
    if len({x['claim']['grade'] for x in selected})>1:flags.append('The matched records mix evidence levels. This is not a direct contradiction or comparative efficacy ranking.')
    return {'query':query,'area':area,'matched':selected,'flags':flags,'contradiction_status':'not_assessed','contradiction_note':'No full-text extraction or aligned endpoint comparison; genuine contradictions cannot be determined automatically.','method':'Deterministic token matching and manual evidence-tier flags; not LLM appraisal or full-text scientific validation.'}
